import {DS18B20} from './ds18b20.js';
import {poweredDevice,pinVoltage} from './bus-electrical.js';
const GPIO=[...Array.from({length:14},(_,i)=>'D'+i),...Array.from({length:6},(_,i)=>'A'+i)];
export function attachOneWireRuntime(runtime,engine,initial){let project=initial,devices=new Map(),disposed=false,refreshing=false,driversKey='',slots=0,resets=0,events=[];
 const commit=()=>{const drivers=[...devices.values()].filter(d=>d.sink&&d.powered&&d.connected).map(d=>({endpoint:d.id+':DQ',voltage:0,ohms:100})),key=JSON.stringify(drivers);if(key!==driversKey){driversKey=key;engine.setDrivers('onewire',drivers);}};
 const schedule=(d,delay,fn)=>{const epoch=d.epoch;runtime.cpu.addClockEvent(()=>{if(disposed||epoch!==d.epoch)return;fn();commit();},Math.max(1,delay));};
 const refresh=()=>{if(disposed||refreshing)return;refreshing=true;try{const dc=engine.solution,board=project.components.find(c=>c.type==='board');for(const[id,d]of devices){const c=project.components.find(c=>c.id===id),power=poweredDevice(dc,id,{vcc:'VDD',min:3});if(d.powered&&!power.powered){d.controller.reset();d.epoch++;d.sink=false;}Object.assign(d,power);d.controller.temperature=c.params.temperature??25;d.controller.tick(runtime.cpu.cycles);const pin=board&&Object.keys(runtime.pinMap).filter(pin=>!runtime.pinMap[pin].analogOnly).find(pin=>dc.netlist.same(id+':DQ',board.id+':'+pin));d.pin=pin;d.connected=!!(power.powered&&pin);if(!d.connected){d.sink=false;d.masterLow=false;continue;}const state=runtime.readPin(pin),low=state.outputEnabled&&!state.high;
  if(low&&!d.masterLow){d.lowSince=runtime.cpu.cycles;d.levelBefore=pinVoltage(dc,id,'DQ');}
  if(!low&&d.masterLow){const width=runtime.cpu.cycles-d.lowSince;if(width>=480*16){d.epoch++;d.sink=false;d.controller.resetBus();resets++;schedule(d,30*16,()=>d.sink=true);schedule(d,150*16,()=>d.sink=false);events.push({cycle:runtime.cpu.cycles,id,kind:'RESET',width});}
   else if(width>=1*16&&width<=120*16){slots++;const response=d.controller.output(runtime.cpu.cycles);if(response!==null&&width<=15*16){if(!response){d.sink=true;schedule(d,Math.max(16,60*16-width),()=>d.sink=false);}events.push({cycle:d.lowSince,id,kind:'READ',bit:response});}else{const bit=width<15*16;d.controller.input(bit,runtime.cpu.cycles);events.push({cycle:d.lowSince,id,kind:'WRITE',bit:Number(bit)});}}
  }d.masterLow=low;d.pullup=Number.isFinite(pinVoltage(dc,id,'DQ'))&&pinVoltage(dc,id,'DQ')>=2.5;
 }if(events.length>256)events=events.slice(-256);commit();}finally{refreshing=false;}};
 const reconcile=()=>{const ids=new Set();for(const c of project.components.filter(c=>c.type==='ds18b20')){ids.add(c.id);if(!devices.has(c.id))devices.set(c.id,{id:c.id,type:c.type,controller:new DS18B20(c.id),epoch:0,powered:false,masterLow:false,sink:false});}for(const[id,d]of devices)if(!ids.has(id)){d.epoch++;devices.delete(id);}refresh();};reconcile();const unsubscribe=engine.subscribe(refresh);
 return{updateProject(next){project=next;reconcile();},snapshot(consume=false){refresh();const result={resets,slots,events:[...events],modules:Object.fromEntries([...devices].map(([id,d])=>[id,{type:d.type,powered:d.powered,connected:d.connected,pullup:d.pullup,voltage:d.voltage,pin:d.pin,...d.controller.state(runtime.cpu.cycles)}]))};if(consume)events=[];return result;},dispose(){disposed=true;for(const d of devices.values())d.epoch++;unsubscribe();engine.setDrivers('onewire',[]);}};
}
